<template>
  <div class="app-container integration-page">
    <div class="heading"><h2>{{t('店铺对接','Store connections')}}</h2><div><el-button :loading="loading" :disabled="busy||acceptanceBlocked" @click="load">{{t('刷新','Refresh')}}</el-button><el-button v-if="configure" type="primary" :disabled="blocked" @click="edit()">{{t('新增连接','Add connection')}}</el-button></div></div>
    <p class="intro">{{t('WooCommerce 订单先进入待审列表，核对来源、商品和已有履约后生成仓库订单。库存回推和快递发货回传仍在开发中。','WooCommerce orders enter an inbox, then become warehouse orders after source, product and fulfillment checks. Stock updates and carrier fulfillment feedback are still being developed.')}}</p>
    <el-alert v-if="acceptanceBlocked&&!reviewOpen" type="warning" :closable="false" class="mb16" :title="t('有接单操作需要继续处理','An acceptance operation needs attention')"><el-button @click="reviewOpen=true">{{t('继续处理','Continue')}}</el-button></el-alert>
    <el-alert v-if="capabilities.localTestMode" type="warning" :closable="false" :title="t('当前为本地测试模式，数据不代表真实店铺。','Local test mode: these records do not establish a live store connection.')" class="mb16" />
    <el-alert v-if="error" type="error" :closable="false" :title="error" class="mb16" />
    <el-alert v-if="pending||pendingError" type="warning" :closable="false" :title="pendingError||t('上次操作的结果尚未确认','The previous operation is unconfirmed')" class="mb16"><template v-if="pending" #default><p class="identifier">{{pending.requestId}}</p><el-button :loading="busy" @click="recover">{{t('查询原请求','Check original request')}}</el-button><el-button v-if="pending.kind==='pull'&&canPull" :loading="busy" @click="retryPull">{{t('重试原拉取','Retry original pull')}}</el-button><el-button v-if="pending.kind==='save'&&configure" :disabled="busy" @click="resumeSave">{{t('重新填写原配置','Re-enter original configuration')}}</el-button></template></el-alert>
    <el-table :data="connections" v-loading="loading" border :empty-text="t('尚未配置店铺连接','No store connections configured')">
      <el-table-column prop="name" :label="t('连接名称','Connection')" min-width="170" /><el-table-column prop="siteUrl" :label="t('店铺网址','Store URL')" min-width="240" show-overflow-tooltip />
      <el-table-column :label="t('状态','Status')" width="110"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?t('已启用','Enabled'):t('已停用','Disabled')}}</el-tag></template></el-table-column>
      <el-table-column :label="t('凭据','Credentials')" width="120"><template #default="s">{{s.row.credentialConfigured?t('已保存','Saved'):t('未配置','Missing')}}</template></el-table-column>
      <el-table-column :label="t('操作','Actions')" width="180" fixed="right"><template #default="s"><el-button v-if="canQuery" link type="primary" :disabled="busy||acceptanceBlocked" @click="open(s.row.id)">{{t('查看','View')}}</el-button><el-button v-if="configure" link type="primary" :disabled="blocked" @click="edit(s.row)">{{t('配置','Configure')}}</el-button></template></el-table-column>
    </el-table>
    <section v-if="selected" class="workspace">
      <div class="heading"><h3>{{selected.name}}</h3><span>{{selected.siteUrl}}</span></div>
      <el-form :inline="true" @submit.prevent="pull(false)">
        <el-form-item v-if="!selected.cursor?.page" :label="t('起点（UTC）','Start (UTC)')"><el-input v-model="since" :aria-label="t('起点（UTC）','Start (UTC)')" placeholder="2026-11-01T00:00:00Z" :disabled="blocked" class="since" /></el-form-item>
        <el-form-item><el-button v-if="canPull" type="primary" :disabled="blocked||!selected.enabled||!selected.credentialConfigured||!selected.hostAllowed" :loading="busy" @click="pull(false)">{{selected.cursor?.page?t('继续下一页','Fetch next page'):t('拉取订单','Fetch orders')}}</el-button><el-button v-if="canPull&&selected.cursor?.page" :disabled="blocked" @click="pull(true)">{{t('重新开始本轮','Restart this window')}}</el-button></el-form-item>
      </el-form>
      <p class="hint">{{selected.cursor?.page?t('当前页','Current page')+': '+selected.cursor.page+' · '+selected.cursor.since+' → '+selected.cursor.until:t('每次最多读取 10 条。留空起点可延续已完成的进度；首次拉取必须填写。','Each request reads up to 10 orders. Leave the start blank to continue a completed window; the first pull requires a start.')}}</p>
      <el-alert v-if="!selected.hostAllowed" class="mb16" type="warning" :closable="false" :title="t('店铺域名尚未加入服务器允许列表，请联系管理员配置后再启用。','The store host is not on the server allowlist. Ask the administrator to configure it before enabling the connection.')" />
      <el-tabs v-model="tab"><el-tab-pane :label="t('订单待审','Order inbox')" name="inbox">
        <el-form :inline="true"><el-form-item :label="t('筛选状态','Filter state')"><el-select v-model="inboxQuery.state" :aria-label="t('筛选状态','Filter state')" clearable style="width:210px" @change="inboxQuery.pageNum=1;loadInbox()"><el-option v-for="state in inboxStates" :key="state" :value="state" :label="stateLabel(state)" /></el-select></el-form-item></el-form>
        <el-table :data="inboxRows" border :empty-text="t('暂无拉取记录','No orders received')"><el-table-column prop="reference" :label="t('平台单号','Store reference')" min-width="170" /><el-table-column prop="external_id" :label="t('平台 ID','External ID')" min-width="150" /><el-table-column :label="t('状态','State')" min-width="170"><template #default="s">{{stateLabel(s.row.state)}}</template></el-table-column><el-table-column :label="t('仓库接单','Warehouse acceptance')" width="150"><template #default="s">{{s.row.warehouse_order_id?t('已接单','Accepted'):t('未接单','Not accepted')}}</template></el-table-column><el-table-column prop="revision" :label="t('版本','Revision')" width="85" /><el-table-column :label="t('操作','Actions')" width="100"><template #default="s"><el-button link type="primary" :disabled="busy" @click="inspect(s.row.id)">{{t('核对','Review')}}</el-button></template></el-table-column></el-table>
        <pagination v-show="inboxTotal>0" :total="inboxTotal" v-model:page="inboxQuery.pageNum" v-model:limit="inboxQuery.pageSize" @pagination="loadInbox" />
      </el-tab-pane><el-tab-pane :label="t('拉取记录','Pull history')" name="jobs">
        <el-table :data="jobRows" border><el-table-column prop="created_at" :label="t('开始时间','Started')" min-width="185" /><el-table-column :label="t('状态','State')" min-width="130"><template #default="s">{{stateLabel(s.row.state)}}<span v-if="s.row.recoverable"> · {{t('可恢复','Recoverable')}}</span></template></el-table-column><el-table-column :label="t('结果','Result')" min-width="260"><template #default="s"><span v-if="s.row.error_code">{{failureLabel(s.row.error_code)}}</span><span v-else-if="s.row.result.received!==undefined">{{t('读取 / 新增 / 更新 / 未变','Read / new / changed / unchanged')}}: {{s.row.result.received}} / {{s.row.result.created}} / {{s.row.result.changed}} / {{s.row.result.unchanged}}</span></template></el-table-column><el-table-column :label="t('恢复','Recovery')" width="120"><template #default="s"><el-button v-if="s.row.recoverable&&canPull&&!pending" link type="primary" :disabled="busy" @click="recoverJob(s.row)">{{t('恢复拉取','Recover pull')}}</el-button></template></el-table-column></el-table>
        <pagination v-show="jobTotal>0" :total="jobTotal" v-model:page="jobQuery.pageNum" v-model:limit="jobQuery.pageSize" @pagination="loadJobs" />
      </el-tab-pane></el-tabs>
    </section>
    <el-drawer v-model="editor" :title="t('连接配置','Connection settings')" size="min(620px,100%)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy" @closed="clearSecrets">
      <el-alert v-if="error" type="error" :closable="false" class="mb16" :title="error" />
      <el-alert v-if="configure&&!capabilities.credentialKeyConfigured" type="warning" :closable="false" class="mb16" :title="t('服务器尚未配置加密密钥，可以先保存停用的连接资料。','The server encryption key is missing. You can save disabled connection details first.')" />
      <el-form label-position="top" :disabled="busy">
        <el-form-item :label="t('连接名称','Connection name')"><el-input v-model="form.name" maxlength="191" /></el-form-item>
        <el-form-item :label="t('店铺网址','Store URL')"><el-input v-model="form.siteUrl" :disabled="!!editId" placeholder="https://shop.example.com" maxlength="512" /></el-form-item>
        <el-form-item v-for="field in routing" :key="field.key" :label="t(field.zh,field.en)"><el-select v-model="form[field.key]" :aria-label="t(field.zh,field.en)" :disabled="!!editId" filterable remote :remote-method="q=>lookup(field.kind,q)" style="width:100%"><el-option v-for="option in withCurrent(field.kind,form[field.key])" :key="option.id" :label="option.label" :value="option.id" :disabled="option.active===false&&option.id!==form[field.key]" /></el-select></el-form-item>
        <p class="hint">{{t('店铺来源、客户、仓库和渠道保存后固定，避免同一来源被重复接单。','Store identity, client, warehouse and channel are fixed after saving to keep source ownership consistent.')}}</p>
        <el-form-item label="Consumer key"><el-input v-model="form.consumerKey" type="password" autocomplete="new-password" :disabled="!capabilities.credentialKeyConfigured" maxlength="512" /></el-form-item>
        <el-form-item label="Consumer secret"><el-input v-model="form.consumerSecret" type="password" autocomplete="new-password" :disabled="!capabilities.credentialKeyConfigured" maxlength="512" /></el-form-item>
        <p class="hint">{{t('密钥不会回显。两项留空保留原凭据；更换时请同时填写。','Credentials are never returned. Leave both fields empty to retain them, or fill both to replace them.')}}</p>
        <el-form-item :label="t('启用连接','Enable connection')"><el-switch v-model="form.enabled" :aria-label="t('启用连接','Enable connection')" /></el-form-item>
      </el-form>
      <template #footer><el-button :disabled="busy" @click="editor=false">{{t('关闭','Close')}}</el-button><el-button type="primary" :loading="busy" @click="save">{{t('保存配置','Save connection')}}</el-button></template>
    </el-drawer>
    <el-drawer v-model="reviewOpen" :title="t('核对平台订单','Review source order')" size="min(820px,100%)">
      <template v-if="detail"><el-alert type="info" :closable="false" class="mb16" :title="t('下方保留平台来源资料。接单区域会核验商品、已有履约和来源归属，并显示关联仓库订单。','Source data is preserved below. Warehouse acceptance verifies products, existing fulfillments and source ownership, and shows the linked warehouse order.')" />
        <el-descriptions :column="width<600?1:2" border class="source-summary"><el-descriptions-item :label="t('平台单号','Reference')">{{detail.document.reference}}</el-descriptions-item><el-descriptions-item :label="t('平台状态','Source status')">{{detail.document.sourceStatus}}</el-descriptions-item><el-descriptions-item :label="t('收件人','Recipient')">{{detail.document.shipping.name}}</el-descriptions-item><el-descriptions-item :label="t('平台金额','Store total')">{{detail.document.total}} {{detail.document.currency}}</el-descriptions-item><el-descriptions-item :span="width<600?1:2" :label="t('收货地址','Address')">{{Object.values(detail.document.shipping).filter(Boolean).join(' · ')}}</el-descriptions-item></el-descriptions>
        <p v-if="detail.document.reasons.length" class="hint">{{t('首次读取时的提示，接单结果以下方实时核验为准：','Initial intake notes; the live acceptance checks below determine eligibility:')}}</p><ul v-if="detail.document.reasons.length" class="reasons"><li v-for="reason in detail.document.reasons" :key="reason">{{reasonLabel(reason)}}</li></ul>
        <h3>{{t('平台商品明细','Source lines')}}</h3><el-table :data="detail.document.lines" border><el-table-column prop="sku" label="SKU" min-width="160" /><el-table-column prop="name" :label="t('名称','Name')" min-width="180" /><el-table-column prop="quantity" :label="t('数量','Quantity')" width="100" /><el-table-column prop="total" :label="t('行金额','Line total')" width="130" /></el-table>
        <p v-if="detail.document.sourceLineCount>detail.document.lines.length">{{t('明细超过展示上限，不能据此接单。','The source exceeds the display limit and cannot be imported from this view.')}}</p>
        <AcceptancePanel :connection="selected" :detail="detail" :disabled="busy||!!pending||!!pendingError" @blocked="acceptanceBlocked=$event" @accepted="inspect(detail.id);loadInbox()" />
        <h3>{{t('来源版本记录','Source revisions')}}</h3><el-table :data="detail.history" border><el-table-column prop="revision" :label="t('版本','Revision')" width="90" /><el-table-column prop="created_at" :label="t('记录时间','Recorded')" min-width="180" /><el-table-column prop="job_id" :label="t('拉取编号','Pull ID')" min-width="260" /></el-table>
      </template>
    </el-drawer>
  </div>
</template>

<script setup name="WarehouseIntegrations">
import {computed,ref,reactive,onMounted,onBeforeUnmount} from 'vue'
import {useWindowSize} from '@vueuse/core'
import {ElMessage} from 'element-plus'
import auth from '@/plugins/auth'
import useUserStore from '@/store/modules/user'
import {bilingual as t} from '@/warehouse/i18n'
import {getWarehouseLookups} from '@/api/warehouse'
import * as api from '@/api/integrations'
import {connectionPayload,pendingMetadata,readIntegrationPending,integrationPendingKey,createdConnectionId} from '@/warehouse/integrations'
import {rejectedBeforeCommit} from '@/warehouse/inventory'
import AcceptancePanel from './AcceptancePanel.vue'
import {acceptancePending,acceptancePendingKey} from '@/warehouse/integration-acceptance'
const user=useUserStore(),{width}=useWindowSize(),configure=computed(()=>Number(user.id)===1&&auth.hasPermi('warehouse:integrations:configure')),canQuery=auth.hasPermi('warehouse:integrations:query'),canPull=auth.hasPermi('warehouse:integrations:pull')
const connections=ref([]),capabilities=ref({}),loading=ref(false),busy=ref(false),error=ref(''),pending=ref(null),pendingError=ref(''),selected=ref(null),since=ref(''),tab=ref('inbox'),inboxRows=ref([]),inboxTotal=ref(0),jobRows=ref([]),jobTotal=ref(0),editor=ref(false),editId=ref(null),form=ref({}),options=reactive({}),reviewOpen=ref(false),detail=ref(null)
const acceptanceBlocked=ref(false),inboxQuery=reactive({pageNum:1,pageSize:20,state:''}),jobQuery=reactive({pageNum:1,pageSize:20}),blocked=computed(()=>busy.value||acceptanceBlocked.value||!!pending.value||!!pendingError.value)
const routing=[{key:'client',kind:'clients',zh:'客户',en:'Client'},{key:'warehouse',kind:'warehouses',zh:'仓库',en:'Warehouse'},{key:'channel',kind:'channels',zh:'销售渠道',en:'Sales channel'}],inboxStates=['AWAITING_REVIEW','HELD','CANCELLED','FULFILLED']
const states={AWAITING_REVIEW:['待核对','Awaiting review'],HELD:['需处理异常','Held for review'],CANCELLED:['平台已取消','Cancelled at source'],FULFILLED:['平台已完成','Completed at source'],RUNNING:['拉取中','Running'],SUCCEEDED:['已完成','Succeeded'],FAILED:['失败','Failed']},stateLabel=state=>t(...(states[state]||[state,state]))
const failures={REMOTE_AUTH_DENIED:['店铺拒绝授权，请核对凭据和权限','Store authorization was denied; check credentials and access'],REMOTE_RATE_LIMITED:['店铺限流，稍后重新拉取','The store rate limit was reached; try again later'],REMOTE_PAGESET_CHANGED:['本轮订单已变化，请重新开始本轮','The order set changed; restart this window'],STORE_HOST_NOT_ALLOWED:['店铺域名未获服务器允许','Store host is not allowed by the server'],CREDENTIAL_KEY_MISSING:['服务器密钥或店铺凭据未配置','Server key or store credentials are missing'],CREDENTIAL_DECRYPTION_FAILED:['凭据无法解密，请核对服务器密钥','Credentials could not be decrypted; check the server key'],REMOTE_CONNECTION_FAILED:['店铺请求失败，请检查网址、网络和证书','Store request failed; check the URL, network and certificate'],ACCESS_REVOKED:['操作权限已撤销','Access was revoked'],CONNECTION_DISABLED:['连接已停用','Connection is disabled'],ROUTING_INACTIVE:['客户、仓库或渠道已停用','Client, warehouse or channel is inactive'],LOCAL_COMMIT_FAILED:['本地提交失败，本页未写入，请重新拉取','Local commit failed; this page was not saved. Fetch again.']},failureLabel=code=>t(...(failures[code]||['未能完成拉取，错误代码：'+code,'Pull could not complete. Error code: '+code]))
const reasons={SOURCE_NOT_PROCESSING:['平台订单尚未进入待处理状态','Source order is not processing'],PAYMENT_UNCONFIRMED:['付款尚未确认','Payment is unconfirmed'],REFUND_INFORMATION_MISSING:['退款资料缺失','Refund information is missing'],REFUNDS_PRESENT:['已有退款，请核对剩余商品','Refunds exist; check the remaining items'],METADATA_INCOMPLETE:['扩展资料不完整','Order metadata is incomplete'],SHIPPING_ADDRESS_INCOMPLETE:['收货地址不完整','Shipping address is incomplete'],ORDER_LINES_MISSING:['缺少订单商品','Order lines are missing'],TOO_MANY_ORDER_LINES:['商品行数超过处理上限','Too many order lines'],SKU_MISSING:['商品缺少 SKU','A line has no SKU'],PRODUCT_UNAVAILABLE:['平台商品不可核验','Source product cannot be verified'],BUNDLE_REQUIRES_REVIEW:['组合商品需要核对','Bundle components require review'],EXISTING_SHIPMENT_INFORMATION:['已有发运资料，需防止重复发货','Existing shipment information requires duplicate-shipping review']},reasonLabel=code=>t(...(reasons[code]||[code,code]))
const message=e=>e?.response?.data?.error?failureLabel(e.response.data.error):e.message||t('操作失败','Operation failed')
function remember(value){const safe=pendingMetadata(value);sessionStorage.setItem(integrationPendingKey(user.id),JSON.stringify(safe));pending.value=safe}
function clearPending(){sessionStorage.removeItem(integrationPendingKey(user.id));pending.value=null}
async function load(){loading.value=true;error.value='';try{const results=await Promise.all([api.integrationConnections(),api.integrationCapabilities()]);connections.value=results[0].data;capabilities.value=results[1].data;if(selected.value&&canQuery)await open(selected.value.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function lookup(kind,q=''){if(!auth.hasPermi('warehouse:'+kind+':list'))return;try{options[kind]=(await getWarehouseLookups(kind,q)).data}catch(e){error.value=message(e)}}
const withCurrent=(kind,id)=>id&&!options[kind]?.some(o=>o.id===id)?[{id,label:id},...(options[kind]||[])]:options[kind]||[]
function edit(row){editId.value=row?.id||null;form.value={name:'',siteUrl:'',client:'',warehouse:'',channel:'',enabled:false,...(row||{}),consumerKey:'',consumerSecret:''};editor.value=true;for(const f of routing)lookup(f.kind)}
function clearSecrets(){form.value.consumerKey='';form.value.consumerSecret=''}
async function save(){if(busy.value||pendingError.value||pending.value&&pending.value.kind!=='save')return;const recovering=!!pending.value;error.value='';busy.value=true;try{const requestId=pending.value?.requestId||crypto.randomUUID(),data=connectionPayload(form.value,requestId),id=editId.value||await createdConnectionId(user.id,requestId);remember({kind:'save',id,requestId,isNew:!editId.value,version:form.value._version});const result=await api.saveIntegration(editId.value,data);clearPending();editor.value=false;await load();await open(result.data.id);ElMessage.success(t('连接已保存','Connection saved'))}catch(e){if(!recovering&&rejectedBeforeCommit(e))clearPending();error.value=message(e)}finally{clearSecrets();busy.value=false}}
let selectedGeneration=0,inboxGeneration=0,jobsGeneration=0
async function open(id){const ticket=++selectedGeneration;try{const row=(await api.integrationConnection(id)).data;if(ticket!==selectedGeneration)return;selected.value=row;inboxQuery.pageNum=1;jobQuery.pageNum=1;await Promise.all([loadInbox(),loadJobs()])}catch(e){error.value=message(e)}}
async function loadInbox(){if(!selected.value)return;const id=selected.value.id,ticket=++inboxGeneration;try{const r=await api.integrationInbox(id,{...inboxQuery});if(ticket===inboxGeneration&&selected.value?.id===id){inboxRows.value=r.data.rows;inboxTotal.value=r.data.total}}catch(e){error.value=message(e)}}
async function loadJobs(){if(!selected.value)return;const id=selected.value.id,ticket=++jobsGeneration;try{const r=await api.integrationJobs(id,{...jobQuery});if(ticket===jobsGeneration&&selected.value?.id===id){jobRows.value=r.data.rows;jobTotal.value=r.data.total}}catch(e){error.value=message(e)}}
async function inspect(item,show=true){try{detail.value=(await api.integrationInboxDetail(selected.value.id,item)).data;reviewOpen.value=show}catch(e){error.value=message(e)}}
async function pull(restartWindow){if(blocked.value)return;const payload={requestId:crypto.randomUUID(),_version:selected.value._version};if(restartWindow)payload.restartWindow=true;else if(!selected.value.cursor?.page&&since.value.trim())payload.since=since.value.trim();try{remember({kind:'pull',id:selected.value.id,requestId:payload.requestId,payload});await retryPull(false)}catch(e){error.value=message(e)}}
async function retryPull(retrying=true){if(busy.value||pending.value?.kind!=='pull')return;busy.value=true;error.value='';try{const r=await api.pullIntegration(pending.value.id,{...pending.value.payload});if(r.data.state==='RUNNING')return;clearPending();await load();if(r.data.state==='FAILED'){error.value=failureLabel(r.data.error_code);tab.value='jobs'}}catch(e){if(!retrying&&rejectedBeforeCommit(e))clearPending();error.value=message(e)}finally{busy.value=false}}
async function recover(){if(busy.value||!pending.value)return;busy.value=true;error.value='';try{const p=pending.value;if(p.kind==='save'){const r=await api.integrationConnection(p.id);if(r.data.lastRequestId!==p.requestId)throw Error(t('尚未查到原配置提交结果，请稍后再查。','The original save is not confirmed yet. Check again later.'));clearPending();editor.value=false;await load();await open(p.id);ElMessage.success(t('已确认原配置保存成功','The original configuration save is confirmed'))}else{const r=await api.integrationJobs(p.id,{pageNum:1,pageSize:100});const job=r.data.rows.find(j=>j.requestId===p.requestId);if(job&&job.state!=='RUNNING'){clearPending();if(job.state==='FAILED')error.value=failureLabel(job.error_code)}await open(p.id)}}catch(e){error.value=message(e)}finally{busy.value=false}}
async function resumeSave(){const p=pending.value;if(p?.kind!=='save')return;if(p.isNew){edit();return}try{edit((await api.integrationConnection(p.id)).data);form.value._version=p.version}catch(e){error.value=message(e)}}
function recoverJob(job){remember({kind:'pull',id:selected.value.id,requestId:job.requestId,payload:{...job.originalInput}});retryPull()}
onMounted(async()=>{try{pending.value=readIntegrationPending(sessionStorage,user.id)}catch{pendingError.value=t('未确认请求的本地记录损坏，请先核对拉取历史，不能直接开始新操作。','The local pending request is invalid. Check history before starting another operation.')}await load();try{const stored=sessionStorage.getItem(acceptancePendingKey(user.id));if(stored){const prior=acceptancePending(JSON.parse(stored));acceptanceBlocked.value=true;await open(prior.connection);if(prior.item)await inspect(prior.item,false)}}catch{pendingError.value=t('接单请求尚未核对，请先恢复原记录。','An acceptance request is unresolved. Recover its original record first.')}})
onBeforeUnmount(clearSecrets)
</script>

